var cacheEj = new Map;
var cargarEjemplos = (k) => {
  if (!cacheEj.has(k))
    cacheEj.set(k, api(`/api/kana/ejemplos?k=${encodeURIComponent(k)}&lang=es`).catch(() => {
      cacheEj.delete(k);
      return [];
    }));
  return cacheEj.get(k);
};
var enviarRonda = (respuestas) => api("/api/kana", { respuestas });
