// src/pantallas/bienvenida-real.ts
var cargarPrueba = () => api("/api/nivel/prueba?lang=es");
async function yaTieneProgreso() {
  try {
    return Number((await api("/api/inicio"))?.cuenta?.aprendidos || 0) > 0;
  } catch {
    return false;
  }
}
async function aplicar(h, yaTiene, kana) {
  let col = null, fallo = false;
  try {
    if (!yaTiene && (h.hasta || kana.length))
      col = await api("/api/nivel", { hasta: h.hasta, kana });
  } catch {
    fallo = true;
  }
  try {
    await api("/api/perfil", { nombre: h.nombre, motivos: h.motivos, minutos: h.minutos, ...yaTiene ? {} : { nivel: h.nivel || "cero", hasta: h.hasta }, hecho: true });
  } catch {
    fallo = true;
  }
  try {
    await api("/api/herencia", {});
  } catch {}
  let d2 = null;
  try {
    d2 = await api("/api/inicio");
  } catch {}
  const reg = col?.region || d2?.region;
  return {
    colocados: Number(col?.colocados || 0),
    region: reg ? { i: Number(reg.i), nombre: String(reg.nombre || "") } : null,
    total: Number(d2?.total_palabras || 3000),
    gramatica: String(d2?.gramatica?.titulo || "").replace(/\[[^\]]*\]/g, ""),
    fallo
  };
}
var deshacerNivel = () => api("/api/nivel/deshacer", {});
var tourVisto = () => {
  api("/api/perfil", { tour: true }).catch(() => null);
};

