    const h = caja.offsetHeight || 190, sobresale = 62;
    const cx = limitar(r.left + r.width / 2 - w / 2, 12, innerWidth - w - 12), cy = limitar(r.top + r.height / 2 - h / 2, sobresale + 12, innerHeight - h - 12);
