    const grande = r.height > innerHeight * 0.42 || r.width > innerWidth * 0.6;
    const orden = grande ? [dcha, izda, abajo, arriba] : r.top + r.height / 2 > innerHeight / 2 ? [arriba, abajo, dcha, izda] : [abajo, arriba, dcha, izda];
    const cabe = (c) => c.x >= 12 && c.x + w <= innerWidth - 12 && c.y >= sobresale + 12 && c.y + h <= innerHeight - 12;
    const pos = orden.find(cabe) ?? { x: cx, y: r.top + r.height / 2 > innerHeight / 2 ? sobresale + 14 : innerHeight - h - 14 };
    const dur = animar && !quieto() ? 0.6 : 0;
    g.to(agujero, { ...hoyo, duration: dur, ease: "back.out(1.25)" });
