function inclinable(el, op = {}) {
  const { fuerza = 12, sobre = el, perspectiva = 0, luz = el } = op;
  if (perspectiva)
    g.set(el, { transformPerspective: perspectiva });
  const rx = g.quickTo(el, "rotationX", { duration: 0.6, ease: "power3" }), ry = g.quickTo(el, "rotationY", { duration: 0.6, ease: "power3" });
  const mover = (e) => {
    const r = sobre.getBoundingClientRect(), px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
    const cx = Math.max(-0.5, Math.min(1.5, px)), cy = Math.max(-0.5, Math.min(1.5, py));
    if (!quieto()) {
      ry((cx - 0.5) * fuerza * 2);
      rx(-(cy - 0.5) * fuerza * 2);
    }
    luz.style.setProperty("--hx", `${cx * 100}%`);
    luz.style.setProperty("--hy", `${cy * 100}%`);
  };
  const salir = () => {
    rx(0);
    ry(0);
  };
  const bajar = () => {
    if (!quieto())
      g.to(el, { scaleX: 1.04, scaleY: 0.94, duration: 0.1, ease: "power2.out" });
  };
  const soltar = () => {
    if (!quieto())
      g.to(el, { scaleX: 1, scaleY: 1, duration: 0.6, ease: "elastic.out(1, 0.35)" });
  };
  sobre.addEventListener("pointermove", mover);
  sobre.addEventListener("pointerleave", salir);
  sobre.addEventListener("pointerdown", bajar);
  sobre.addEventListener("pointerup", soltar);
  sobre.addEventListener("pointercancel", soltar);
  return () => {
    sobre.removeEventListener("pointermove", mover);
    sobre.removeEventListener("pointerleave", salir);
    sobre.removeEventListener("pointerdown", bajar);
    sobre.removeEventListener("pointerup", soltar);
    sobre.removeEventListener("pointercancel", soltar);
  };
}
