var guardarLectura = (id, aciertos, total, opinion) => api(`/api/lectura/${encodeURIComponent(id)}`, { aciertos, total, opinion }).catch(() => null);
function cargarHistoria(id) {
  let p = historias.get(id);
  if (!p) {
    p = fetch(ruta(`lecturas/${encodeURIComponent(id)}.json`)).then((r) => r.ok ? r.json() : null).catch(() => null);
    historias.set(id, p);
  }
  return p;
}
var cargarVoces2 = (id) => fetch(ruta(`sonidos/lecturas/${encodeURIComponent(id)}/indice.json`)).then((r) => r.ok ? r.json() : []).then((a) => new Set(a)).catch(() => new Set);
var portada = (id) => `img/historias/${encodeURIComponent(id)}.webp`;
var guardado = (k, def) => {
  try {
    const v = localStorage.getItem(k);
    return v === null ? def : v === "1";
  } catch {
    return def;
  }
};
var guardar = (k, v) => {
  try {
    localStorage.setItem(k, v ? "1" : "0");
  } catch {}
};
