var PALABRAS = {
  "活用": "かつよう",
  "動詞": "どうし",
  "形容詞": "けいようし",
  "五段": "ごだん",
  "一段": "いちだん",
  "サ変": "さへん",
  "カ変": "かへん",
  "音便": "おんびん",
  "五段活用": "ごだんかつよう",
  "一段活用": "いちだんかつよう",
  "サ変活用": "さへんかつよう",
  "カ変活用": "かへんかつよう",
  "い形容詞": "いけいようし",
  "な形容詞": "なけいようし",
  "来る": "くる",
  "名前": "なまえ"
};
var NOMBRES2 = Object.keys(BASES);
function baseRuby(texto, dominado = false) {
  texto = String(texto ?? "");
  const b = BASES[texto];
  if (b)
    return dominado ? texto : `${texto}[${b.lectura}]`;
  const l = PALABRAS[texto];
  if (l) {
    const m = texto.match(/^([ぁ-ゖァ-ヺ]*)(.*?)([ぁ-ゖァ-ヺ]*)$/);
    const pre = m[1], medio = m[2], post = m[3];
    const lm = l.slice(pre.length ? [...pre].length : 0, post.length ? -[...post].length : undefined);
    return `${pre}${pre ? " " : ""}${medio}[${lm}]${post}`;
  }
  return furiBases(texto, dominado);
}
var EN_FRASE = [...Object.keys(BASES), ...Object.keys(PALABRAS).filter((k) => k !== "来る")].sort((a, b) => b.length - a.length);
var RE_FRASE = new RegExp(`(${EN_FRASE.join("|")})(?!\\[)`, "g");
function furiBases(texto, dominado = false) {
  return String(texto ?? "").replace(RE_FRASE, (k) => baseRuby(k, dominado));
}

