function pintarTodo(raiz) {
  raiz.innerHTML = `<div class="cg" data-fase="lista" data-racha="0">${calorHtml()}<header class="p-arriba cg-arriba"></header><main class="cg-cuerpo" id="cg-cuerpo"></main></div>`;
  G2 = { cargando: false, raiz: $(".cg", raiz), fase: "lista", tab: "verbos", ronda: null, tut: null, ultima: "", temporizadores: [], token: 0 };
  pintarLista(true);
  animarLetras($(".cg-arriba h1", G2.raiz));
  const clic = (e) => {
    const t = e.target;
    if (t.closest("[data-cerrar]")) {
      if (G2.fase === "lista") {
        S(() => papel());
        app.cerrar();
      } else
        volverALista();
      return;
    }
    const tab = t.closest("[data-tab]");
    if (tab) {
      cambiarPestana(tab.dataset.tab);
      return;
    }
    const ficha = t.closest(".cg-ficha[data-id]");
    if (ficha && G2.fase === "lista") {
      sonar2("clic");
      S(() => toque());
      empezar2(ficha.dataset.id, ficha);
      return;
    }
    if (t.closest("[data-ayuda]")) {
      sonar2("clic");
      abrirTutorial();
      return;
    }
    if (t.closest("[data-repasar]")) {
      sonar2("pop");
      app.repaso("conjugacion");
      return;
    }
    if (t.closest("[data-sig]")) {
      sonar2("clic");
      siguiente();
      return;
    }
    if (t.closest("[data-comp]")) {
      pulsarIntro();
      return;
    }
    if (t.closest("[data-formas]")) {
      volverALista();
      return;
    }
    if (t.closest("[data-otra]")) {
      sonar2("clic");
      empezar2(G2.ronda.forma.id, t.closest("[data-otra]"));
    }
  };
  raiz.addEventListener("click", clic);
  const enviar = (e) => {
    if (e.target.closest(".cg-resp")) {
      e.preventDefault();
      pulsarIntro();
    }
  };
  raiz.addEventListener("submit", enviar);
  const tecla = (e) => {
    if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.altKey || e.isComposing || G2.tut)
      return;
    const k = e.key, t = e.target instanceof Element ? e.target : G2.raiz;
    if (k === "Escape") {
      e.preventDefault();
      if (G2.fase === "lista") {
        S(() => papel());
        app.cerrar();
      } else
        volverALista();
      return;
    }
    if (G2.fase === "lista") {
      if (/^[1-3]$/.test(k)) {
        e.preventDefault();
        cambiarPestana(PESTANAS[Number(k) - 1][0]);
        return;
      }
      if (k.startsWith("Arrow")) {
        e.preventDefault();
        moverFoco(k);
        return;
      }
      if (k === "Enter" && !t.closest("button")) {
        e.preventDefault();
        ($(`.cg-ficha[data-id="${G2.ultima}"]`, G2.raiz) ?? $(".cg-ficha", G2.raiz))?.click();
      }
      return;
    }
    if (G2.fase === "fin") {
      if (k === "Enter" && !t.closest("button")) {
        e.preventDefault();
        $("[data-otra]", G2.raiz)?.click();
      }
      return;
    }
    if (k === "Enter") {
      const b = t.closest("button");
      if (b && !b.classList.contains("cg-sig") && !b.classList.contains("cg-comp"))
        return;
      e.preventDefault();
      pulsarIntro();
    }
  };
  document.addEventListener("keydown", tecla);
  if (!tutorialVisto())
    ya2(() => {
      if (G2.fase === "lista" && !G2.tut)
        abrirTutorial();
    }, 750);
  return () => {
    raiz.removeEventListener("click", clic);
    raiz.removeEventListener("submit", enviar);
    document.removeEventListener("keydown", tecla);
    G2.tut?.cierra();
    G2.temporizadores.forEach((t) => clearTimeout(t));
    G2.token++;
  };
}

