var primeras = null;
var cargarPrimeraN = () => primeras ??= fetch("/datos/contenido.es.json").then((r) => r.ok ? r.json() : null).then((d) => {
  if (!d)
    return null;
  const m = new Map;
  for (const [id, it] of Object.entries(d.items))
    if (it.tipo === "kanji" && it.primera_n)
      m.set(id, it.primera_n);
  return m;
}).catch(() => null);
var fichas = new Map;
function fichaDe(id) {
  let p = fichas.get(id);
  if (!p) {
    p = api(`/api/item/${encodeURIComponent(id)}`).then((x) => {
      const d = x.item ?? x, f = aFicha(d);
      const furi = new Map((d.palabras || []).map((w) => [w.palabra, w.furigana || w.palabra]));
      const con = (d.vocab_con || []).slice().sort((a, b) => Number(!!b.aprendido) - Number(!!a.aprendido)).slice(0, 8);
      if (con.length)
        f.palabras = con.map((w) => ({ f: furi.get(w.palabra) ?? w.palabra, es: w.es || "" }));
      return f;
    });
    p.catch(() => fichas.delete(id));
    fichas.set(id, p);
  }
  return p;
}
async function trazosDe2(c) {
  await cargarTrazos([c]);
  return TRAZOS[c]?.d ?? [];
}

