// src/pantallas/jefe-real.ts
async function cargarFicha2(i) {
  const juego = await api("/api/juego").catch(() => null);
  const e = juego?.jefes?.find((x) => Number(x.region) === i);
  if (!e)
    return null;
  const dormido = !e.desbloqueado;
  const j = { id: e.id, jp: e.jp, nombre: e.nombre, vida: Math.max(1, Number(e.vida) || 100), tono: TONO[e.id] ?? "#c07a3a", desc: e.desc ?? "", titulo: e.titulo ?? "", nivel: Number(e.nivel) || 1, img: e.img ?? `img/jefes/${e.id}.svg`, vencido: !!e.vencido };
  const reg = { i, nom: e.region_nombre ?? "", jp: e.region_jp ?? "", aprendidas: Number(e.aprendidas) || 0, total: Number(e.total) || 0, necesarias: Number(e.necesarias) || 0 };
  let plan = null;
  if (dormido) {
    const p = await api(`/api/region/${i}/preparacion`).catch(() => null);
    const det = p?.siguientes_detalle ?? [];
    plan = {
      faltan: Math.max(0, Number(p?.faltan ?? reg.necesarias - reg.aprendidas) || 0),
      aprendidas: Number(p?.aprendidas ?? reg.aprendidas) || 0,
      practica: !!(p?.practica_disponible ?? false) && (Number(p?.aprendidas ?? reg.aprendidas) || 0) > 0,
      palabras: det.slice(0, 7).map((d) => ({ p: String(d.palabra ?? ""), lec: String(d.lectura ?? ""), es: String(d.es ?? "") })).filter((d) => d.p),
      gramatica: (p?.gramatica ?? []).filter((x) => x?.slug).slice(0, 3).map((x) => ({ slug: String(x.slug), titulo: String(x.titulo || x.slug), hecha: !!x.hecha }))
    };
  }
  return { j, reg, dormido, vencido: !!e.vencido, plan };
}
async function regionQueToca() {
  const juego = await api("/api/juego").catch(() => null);
  const l = juego?.jefes ?? [];
  const e = l.find((x) => !x.vencido) ?? l[0];
  return e ? Number(e.region) : 0;
}
var textoRespuesta = (it, hab) => {
  if (hab === "sig")
    return it.tipo === "radical" ? it.nombre : it.tipo === "kanji" ? it.clave : it.es || it.en || "";
  if (it.tipo === "kanji") {
    const u = (it.lecturas || []).map((l) => l.lectura);
    return [...new Set(u.length ? u : it.lecturas_validas || [])].join("、");
  }
  return it.lectura || "";
};
function aPreg(q) {
  const it = q.item, hab = q.habilidad === "lec" ? "lec" : "sig";
  const sigs = validasSig(it).filter(Boolean).map(String), lecs = validasLec(it).filter(Boolean).map(String);
  return {
    id: String(it.id),
    tipo: it.tipo,
    texto: String((it.tipo === "vocab" ? it.palabra : it.caracter) || "？"),
    hab,
    sigs,
    validas: hab === "sig" ? sigs : lecs,
    resp: String(textoRespuesta(it, hab)),
    truco: String((hab === "lec" && it.mnemo_lectura ? it.mnemo_lectura : it.mnemo) || ""),
    ejemplo: it.tipo === "vocab" && it.frase_furigana ? { jp: String(it.frase_furigana), es: String(it.frase_es || "") } : null
  };
}
async function pedirCombate(i) {
  const d = await api(`/api/jefe/${i}`).catch(() => null);
  const l = (d?.preguntas ?? []).map(aPreg);
  return l.length ? l : null;
}
async function enviarResultado(i, ganado, aciertos, total) {
  const r = await api(`/api/jefe/${i}/resultado`, { ganado, aciertos, total }).catch(() => null);
  if (!r)
    return null;
  const rc = r.recompensa ?? {}, o = rc.objeto ?? null;
  return { ganado: !!r.ganado, recompensa: {
    objeto: o ? { id: o.id, nombre: o.nombre, jp: o.jp ?? "", desc: o.desc ?? "", rareza: o.rareza ?? "epico", rarezaNombre: o.rareza_nombre ?? "", color: o.color || "#f2b43a" } : null,
    monedas: Number(rc.monedas) || 0,
    titulo: String(rc.titulo || ""),
    tope: !!rc.tope_diario
  } };
}

