async function cargar3() {
  const [ini, e] = await Promise.all([api("/api/inicio"), api("/api/estadisticas")]);
  const dias = (e.dias || []).map((d) => ({ dia: String(d.dia), n: d.respuestas || 0, s: d.s || 0, estudio: !!(d.respuestas || d.s) }));
  const hoy = dias[dias.length - 1];
  const E = {
    racha: ini.racha || 0,
    hoyHecho: !!hoy?.estudio,
    dias,
    aciertos: e.aciertos_semana ?? null,
    tiempoTotal: e.tiempo_total || 0,
    tiempoSemana: e.tiempo_semana || 0,
    tiempoAprox: !!e.tiempo_aprox,
    xp: ini.xp || 0,
    palabras: e.aprendidas?.vocab || 0,
    totalPalabras: e.totales?.vocab || 0,
    kanji: e.aprendidas?.kanji || 0,
    totalKanji: e.totales?.kanji || 0,
    clases: ini.gramatica_hechas || 0,
    totalClases: ini.gramatica_total || 0,
    claseMedia: e.clases_media ?? null,
    historias: ini.lecturas_leidas || 0,
    totalHistorias: ini.lecturas_total || 0,
    nyanSabe: ini.nyan_sabe || 0,
    repasos: ini.repasos_ahora || 0
  };
  const pasos = [];
  if (ini.repasos_ahora) {
    pasos.push({
      id: "rep",
      icono: "repaso",
      tit: ini.repasos_ahora === 1 ? "1 repaso" : `${ini.repasos_ahora} repasos`,
      sub: `Lo que ya sabes, antes de que se olvide · unos ${Math.max(1, Math.round(ini.repasos_ahora * 0.35))} min`,
      jp: "まずは復習！",
      dice: "Las cartas primero: ¡antes de que se te olviden!",
      peg: "animo"
    });
  }
  if (ini.gramatica) {
    pasos.push({
      id: "clase",
      icono: "clase",
      tit: `${esc2(ini.gramatica.capitulo)} · ${ruby(ini.gramatica.titulo || "")}`,
      sub: "La gramática que necesitan tus próximas palabras",
      jp: "クラスだよ！",
      dice: "Una clase nueva para tus próximas palabras.",
      peg: "bien",
      arg: ini.gramatica.slug
    });
  }
  const nuevas = ini.leccion?.palabras || [];
  if (nuevas.length) {
    pasos.push({
      id: "nuevas",
      icono: "w-palabra",
      tit: nuevas.length === 1 ? "1 palabra nueva" : `${nuevas.length} palabras nuevas`,
      sub: "",
      subJp: nuevas.slice(0, 4).join("、"),
      jp: "新しいことば！",
      dice: `${nuevas.length === 1 ? "Una palabra" : `${nuevas.length} palabras`} para mi libreta. ¡Qué ganas!`,
      peg: "bien"
    });
  }
  if (ini.lectura) {
    pasos.push({
      id: "historia",
      icono: "historias",
      tit: "Historia nueva: ",
      titJp: sinFuri(ini.lectura.titulo?.jp || ""),
      sub: "Ya tienes todas sus palabras",
      jp: "お話の時間！",
      dice: "¡Un cuento con todas sus palabras! Tú ya puedes leerlo.",
      peg: "asoma",
      arg: ini.lectura.id
    });
  }
  return { E, pasos };
}
var DE_ESTUDIO = new Set(["leccion", "clase", "historias", "guia", "conjugar", "kana", "kanji", "jefe", "bienvenida"]);
var activo2 = Date.now();
var pendiente = 0;
var en_marcha = false;
var pasar = () => {
  if (!pendiente)
    return;
  const s = pendiente;
  pendiente = 0;
  api("/api/tiempo", { s }).catch(() => {
    pendiente += s;
  });
};
var estudiando = () => {
  const ses = document.getElementById("sesion"), pan = document.getElementById("pantalla");
  if (ses && !ses.hidden)
    return true;
  return !!pan && !pan.hidden && DE_ESTUDIO.has(pan.dataset.p || "");
};
function relojEstudio() {
  if (en_marcha)
    return;
  en_marcha = true;
  for (const ev of ["keydown", "pointerdown", "wheel", "touchstart"])
    addEventListener(ev, () => {
      activo2 = Date.now();
    }, { passive: true, capture: true });
  setInterval(() => {
    if (document.visibilityState !== "visible" || Date.now() - activo2 > 60000 || !estudiando())
      return;
    pendiente += 5;
    if (pendiente >= 30)
      pasar();
  }, 5000);
  addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden")
      pasar();
  });
  addEventListener("nyango:cerrar", pasar);
}

