function agrupar(texto) {
  const c = String(texto || "").toUpperCase().replace(/O/g, "0").replace(/[IL]/g, "1").replace(/[^0-9A-HJKMNP-TV-Z]/g, "").slice(0, 26);
  const trozos = [];
  let i = 0;
  for (const n of [4, 4, 4, 4, 4, 6]) {
    if (i >= c.length)
      break;
    trozos.push(c.slice(i, i + n));
    i += n;
  }
  return trozos.join("-");
}
function sacarCodigo(texto) {
  let x = String(texto || "").trim();
  const m = x.match(/enlazar=([^&\s]+)/i);
  if (m)
    x = decodeURIComponent(m[1]);
  const gr = agrupar(x);
  return gr.replace(/-/g, "").length === 26 ? gr : "";
}
var rtf = new Intl.RelativeTimeFormat("es", { numeric: "auto", style: "short" });
function haceCuanto(ts) {
  if (!ts)
    return "";
  const s = Date.now() / 1000 - ts;
  if (s < 45)
    return ENLACE.ahoraMismo;
  if (s < 3600)
    return rtf.format(-Math.max(1, Math.round(s / 60)), "minute");
  if (s < 86400)
    return rtf.format(-Math.round(s / 3600), "hour");
  return rtf.format(-Math.round(s / 86400), "day");
}
async function qrSvg(texto) {
  const url = new URL("vendor/qr/qr.js", location.href).href;
  const m = await import(url);
  const filas = m.encodeQR(texto, "raw", { ecc: "medium", border: 0 }), n = filas.length, b = 3;
  let d = "";
  filas.forEach((fila, y) => {
    let x = 0;
    while (x < n) {
      if (!fila[x]) {
        x++;
        continue;
      }
      let w = 1;
      while (x + w < n && fila[x + w])
        w++;
      d += `M${x + b} ${y + b}h${w}v1h${-w}z`;
      x += w;
    }
  });
  const L = n + 2 * b;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${L} ${L}" shape-rendering="crispEdges" role="img" aria-label="Código QR para vincular el móvil"><rect width="${L}" height="${L}" fill="#ffffff"/><path d="${d}" fill="#3b2a1c"/></svg>`;
}
var nombreCopia = (d = new Date) => `nyango-progreso-${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}.json`;

// src/pantallas/ajustes-real.ts
async function cargarAjustes() {
  const [ini, est] = await Promise.all([api("/api/inicio"), api("/api/estadisticas").catch(() => ({}))]);
  const a = ini.ajustes || {}, v = (k) => typeof a[k] === "number" ? a[k] : 100;
  return {
    modo: a.modo_repaso || "mixto",
    sonido: a.sonido !== false,
    autoplay: a.autoplay !== false,
    musica: a.musica !== false,
    vol: { musica: v("vol_musica"), efectos: v("vol_efectos"), voz: v("vol_voz") },
    idioma: a.idioma === "en" ? "en" : "es",
    deNivel: ini.de_nivel || 0,
    resumen: { palabras: est.aprendidas?.vocab || 0, kanji: est.aprendidas?.kanji || 0, xp: ini.xp || 0, racha: ini.racha || 0 }
  };
}
var guardarAjuste = (d) => {
  api("/api/ajustes", d).catch(() => {});
};
var TEMAS_MOTOR = ["washi", "noche", "pop", "sumi"];
var ponerIdioma = (i) => cambiarIdioma(i);
var deshacerPrueba = () => api("/api/nivel/deshacer", {});
var exportarProgreso = () => api("/api/progreso/exportar");
var importarProgreso = (texto) => api("/api/progreso/importar", { texto });
var enlaceEstado = () => api("/api/enlace").catch(() => null);
var enlaceCrear = (nombre = "") => api("/api/enlace/crear", { nombre });
var enlaceUnir = (codigo, nombre = "") => api("/api/enlace/unir", { codigo, nombre });
var enlaceAhora = () => api("/api/enlace/ahora", {});
var enlaceQuitar = () => api("/api/enlace/quitar", {});
var enlaceNombre = (nombre) => api("/api/enlace/nombre", { nombre });
async function aplicarAjustesGuardados() {
  const ini = await api("/api/inicio"), a = ini.ajustes || {};
  const sx = exports_sonido;
  const vol = (k) => typeof a[k] === "number" ? a[k] / 100 : 1;
  if (a.sonido === false)
    app.sonido(false);
  sx.volumenes?.({ musica: vol("vol_musica"), efectos: vol("vol_efectos"), voz: vol("vol_voz") });
  sx.permitirMusica?.(a.musica !== false);
  let hay = false;
  try {
    hay = localStorage.getItem("nyango-tema") !== null;
  } catch {}
  if (!hay && TEMAS_MOTOR.includes(a.tema))
    app.tema(a.tema);
}

